const items = $input.all();

return items.map(item => {
  const body = item.json.body ?? item.json;

  if (typeof body.sample_id !== "string" ||
      !body.sample_id.trim()) {
    throw new Error("Missing or invalid sample_id");
  }

  if (typeof body.code !== "string" ||
      !body.code.trim()) {
    throw new Error("Missing or invalid code");
  }

  return {
    json: {
      sample_id: body.sample_id,
      code: body.code,
      tests: body.tests ?? ""
    }
  };
});

const data=$input.first().json,code=data.code??"",findings=[];
code.split("\n").forEach((s,i)=>{
if(/def\s+\w+\([^)]*=\s*\[\]/.test(s))findings.push({agent:"Bug Analysis",severity:"HIGH",line:i+1,title:"Mutable default argument",recommendation:"Use None as the default."});
if(/return\s+total\s*\/\s*count/.test(s))findings.push({agent:"Bug Analysis",severity:"MEDIUM",line:i+1,title:"Potential division by zero",recommendation:"Check count before division."});
});
return [{json:{sample_id:data.sample_id,bug_findings:findings}}];

const data=$input.first().json,code=data.code??data.body?.code??"",findings=[];
function add(rule,severity,line,title,recommendation){findings.push({agent:"security",rule,severity,line,title,recommendation});}
code.split("\n").forEach((s,i)=>{
const line=i+1;
if(/\b(SELECT|UPDATE|INSERT|DELETE)\b/i.test(s)&&(/(\+|f["']|\.format\()/.test(s)))add("SEC-SQL-INJECTION","CRITICAL",line,"Potential SQL injection","Use parameterized queries.");
if(/shell\s*=\s*True|\bos\.system\s*\(/.test(s))add("SEC-SHELL","HIGH",line,"Shell command execution","Use shell=False with argument arrays.");
if(/\bpickle\.loads?\s*\(/.test(s))add("SEC-PICKLE","HIGH",line,"Unsafe deserialization","Do not deserialize untrusted pickle data.");
if(/\b(eval|exec)\s*\(/.test(s))add("SEC-EVAL","CRITICAL",line,"Dynamic evaluation of input","Avoid eval/exec on untrusted data.");
});
return [{json:{sample_id:data.sample_id,agent:"security",findings:[...new Map(findings.map(f=>[f.rule+":"+f.line,f])).values()]}}];

const data=$input.first().json,code=data.code??"",findings=[];
function add(title,recommendation){findings.push({agent:"Test Coverage",severity:"MEDIUM",title,recommendation});}
if(!String(data.tests??"").trim())add("No tests provided","Add unit tests.");
if(/=\s*\[\]/.test(code))add("Missing mutable-default test","Test repeated calls.");
if(/return\s+total\s*\/\s*count/.test(code))add("Missing zero-divisor test","Test count=0.");
if(/\bSELECT\b/i.test(code))add("Missing SQL input tests","Test parameter handling and invalid inputs.");
if(/\bpickle\.loads?\s*\(/.test(code))add("Missing deserialization tests","Test rejection of untrusted data.");
return [{json:{sample_id:data.sample_id,test_findings:findings}}];

const items=$input.all(),all=[];
for(const {json:d} of items)for(const key of ["bug_findings","security_findings","test_findings","findings"])if(Array.isArray(d[key]))all.push(...d[key]);
const rank={CRITICAL:4,HIGH:3,MEDIUM:2,LOW:1},seen=new Set();
const findings=all.map(f=>({...f,severity:String(f.severity??"LOW").toUpperCase()})).filter(f=>{const k=[f.agent,f.rule??f.title,f.line??""].join("|");if(seen.has(k))return false;seen.add(k);return true;}).sort((a,b)=>(rank[b.severity]??0)-(rank[a.severity]??0));
const summary={critical:0,high:0,medium:0,low:0,total:findings.length};
for(const f of findings)if(f.severity.toLowerCase() in summary)summary[f.severity.toLowerCase()]++;
return [{json:{sample_id:items[0]?.json.sample_id??"unknown",status:summary.critical||summary.high?"CHANGES_REQUIRED":"REVIEW_COMPLETE",summary,findings,debug:{received_items:items.length,findings_collected:findings.length}}}];
